# logs.py: una línea JSON por request con el patrón try/except/finally de C01 (simulación, solo stdlib)
import json, time

class HTTPError(Exception):  # hace el papel de HTTPException
    def __init__(self, status, detail):
        self.status, self.detail = status, detail

def trabajo(modo):
    if modo == "saturado":
        raise HTTPError(503, "gateway saturado: reintenta más tarde")
    if modo == "lento":
        raise HTTPError(504, "timeout de inferencia")
    if modo == "bug":
        return {}["logits"]  # un bug: KeyError
    return {"predictions": []}

def classify(modo, request_id):
    t0 = time.perf_counter()
    record = {"event": "classify", "request_id": request_id, "model_version": "2026-09-01-resnet50-fp16"}
    status = 500  # si algo inesperado explota, se cuenta como 500
    try:
        resultado = trabajo(modo)
        status = 200
        return resultado
    except HTTPError as exc:
        status = exc.status
        record["error"] = exc.detail
        raise
    finally:  # corre SIEMPRE: con éxito, con HTTPError y con el bug
        record.update(status=status, latency_ms=round((time.perf_counter() - t0) * 1000, 1))
        print(json.dumps(record, ensure_ascii=False), flush=True)

for i, modo in enumerate(["ok", "ok", "saturado", "lento", "bug"]):
    try:
        classify(modo, f"req-{i}")
    except Exception as exc:
        pass  # en el gateway real, el cliente recibe el error (y el bug, un 500)
EOF
